INSERT INTO `chat_messages` (`message_id`, `session_id`, `message_type`, `content`, `sent_at`) VALUES
(1, 1, 'user', 'السلام عليكم', '2025-11-26 21:30:59'),
(2, 1, 'assistant', 'وعليكم السلام! كيف يمكنني مساعدتك اليوم في مجال التغذية؟', '2025-11-26 21:30:59'),
(3, 1, 'user', 'ماذا تعرف عن صحتي', '2025-11-26 21:31:18'),
(4, 1, 'assistant', 'للأسف، لا أستطيع تقديم معلومات دقيقة حول صحتك دون معرفة تفاصيل مثل العمر، الوزن، الطول، مستوى النشاط، وفصيلة الدم. إذا كنت بحاجة إلى نصائح غذائية أو استشارات صحية، يُفضل مشاركة هذه المعلومات لنتمكن من مساعدتك بشكل أفضل.', '2025-11-26 21:31:18'),
(5, 6, 'user', 'السلام', '2025-12-01 20:53:19'),
(6, 6, 'assistant', 'مرحبًا رماس! كيف يمكنني مساعدتك اليوم في مجال التغذية؟', '2025-12-01 20:53:19'),
(7, 6, 'user', 'السلام', '2025-12-01 22:28:52'),
(8, 6, 'assistant', 'وعليكم السلام، ريمس! كيف يمكنني مساعدتك اليوم في ما يتعلق بالتغذية أو الصحة؟', '2025-12-01 22:28:52'),
(9, 6, 'user', 'السلام', '2025-12-02 18:58:36'),
(10, 6, 'assistant', 'مرحبًا ريمس! كيف يمكنني مساعدتك اليوم في موضوع التغذية؟', '2025-12-02 18:58:36'),
(11, 7, 'user', 'What services do you offer me?', '2025-12-02 21:59:56'),
(12, 7, 'assistant', 'As your nutrition assistant, I can provide you with tailored advice on meal planning, food choices, and dietary adjustments based on your blood type (O+), activity level, and any chronic conditions or food allergies you may have. I can help you:\n\n1. Create balanced meal plans.\n2. Suggest foods that align with your blood type.\n3. Offer tips for managing weight and energy levels.\n4. Provide guidance on nutrient-rich foods for your lifestyle.\n\nFeel free to ask specific questions or request help with a particular topic!', '2025-12-02 21:59:56');
