INSERT INTO `health_rules` (`id`, `rule_type`, `rule_key`, `rule_data`, `created_at`) VALUES
(1, 'blood_type_rules', 'O', '{\"description\": \"فصيلة O (الصياد) - نظام غذائي غني بالبروتين\", \"beneficial\": [\"لحوم حمراء\", \"أسماك\", \"خضروات ورقية\", \"بروكلي\", \"سبانخ\"], \"avoid\": [\"قمح\", \"ذرة\", \"بقوليات\", \"عدس\", \"منتجات ألبان\"], \"recommendations\": [\"التركيز على البروتينات الحيوانية\", \"تجنب الحبوب والبقوليات\"]}', '2025-11-26 21:18:45'),
(2, 'blood_type_rules', 'A', '{\"description\": \"فصيلة A (المزارع) - نظام غذائي نباتي\", \"beneficial\": [\"خضروات\", \"فواكه\", \"حبوب\", \"بقوليات\", \"توفو\", \"أسماك\"], \"avoid\": [\"لحوم حمراء\", \"منتجات ألبان\", \"قمح\", \"فاصوليا\"], \"recommendations\": [\"التركيز على الأطعمة النباتية\", \"تجنب اللحوم الحمراء\"]}', '2025-11-26 21:18:45'),
(3, 'blood_type_rules', 'B', '{\"description\": \"فصيلة B (البدوي) - نظام غذائي متوازن\", \"beneficial\": [\"ألبان\", \"بيض\", \"خضروات خضراء\", \"لحوم\", \"أسماك\"], \"avoid\": [\"ذرة\", \"عدس\", \"فول سوداني\", \"دجاج\"], \"recommendations\": [\"نظام غذائي متنوع\", \"تجنب الدجاج والذرة\"]}', '2025-11-26 21:18:45'),
(4, 'blood_type_rules', 'AB', '{\"description\": \"فصيلة AB (الغامض) - نظام غذائي مختلط\", \"beneficial\": [\"مأكولات بحرية\", \"توفو\", \"منتجات ألبان\", \"خضروات خضراء\"], \"avoid\": [\"لحوم حمراء\", \"فاصوليا\", \"بذور\", \"ذرة\"], \"recommendations\": [\"مزيج من أنظمة A و B\", \"تجنب اللحوم الحمراء والفاصوليا\"]}', '2025-11-26 21:18:45'),
(5, 'blood_type_rules', 'O', '{\"description\": \"فصيلة O (الصياد) - نظام غذائي غني بالبروتين\", \"beneficial\": [\"لحوم حمراء\", \"أسماك\", \"خضروات ورقية\", \"بروكلي\", \"سبانخ\"], \"avoid\": [\"قمح\", \"ذرة\", \"بقوليات\", \"عدس\", \"منتجات ألبان\"], \"recommendations\": [\"التركيز على البروتينات الحيوانية\", \"تجنب الحبوب والبقوليات\"]}', '2025-11-27 22:51:40'),
(6, 'blood_type_rules', 'A', '{\"description\": \"فصيلة A (المزارع) - نظام غذائي نباتي\", \"beneficial\": [\"خضروات\", \"فواكه\", \"حبوب\", \"بقوليات\", \"توفو\", \"أسماك\"], \"avoid\": [\"لحوم حمراء\", \"منتجات ألبان\", \"قمح\", \"فاصوليا\"], \"recommendations\": [\"التركيز على الأطعمة النباتية\", \"تجنب اللحوم الحمراء\"]}', '2025-11-27 22:51:40'),
(7, 'blood_type_rules', 'B', '{\"description\": \"فصيلة B (البدوي) - نظام غذائي متوازن\", \"beneficial\": [\"ألبان\", \"بيض\", \"خضروات خضراء\", \"لحوم\", \"أسماك\"], \"avoid\": [\"ذرة\", \"عدس\", \"فول سوداني\", \"دجاج\"], \"recommendations\": [\"نظام غذائي متنوع\", \"تجنب الدجاج والذرة\"]}', '2025-11-27 22:51:40'),
(8, 'blood_type_rules', 'AB', '{\"description\": \"فصيلة AB (الغامض) - نظام غذائي مختلط\", \"beneficial\": [\"مأكولات بحرية\", \"توفو\", \"منتجات ألبان\", \"خضروات خضراء\"], \"avoid\": [\"لحوم حمراء\", \"فاصوليا\", \"بذور\", \"ذرة\"], \"recommendations\": [\"مزيج من أنظمة A و B\", \"تجنب اللحوم الحمراء والفاصوليا\"]}', '2025-11-27 22:51:40'),
(9, 'disease_rules', 'diabetes', '{\"recommended\": [\"خضروات ورقية\", \"أسماك\", \"بقوليات\", \"مكسرات\"], \"avoid\": [\"سكريات\", \"عصائر\", \"خبز أبيض\", \"أرز أبيض\"], \"guidelines\": \"التحكم في كربوهيدرات، التركيز على الألياف\"}', '2025-11-27 22:51:40'),
(10, 'disease_rules', 'hypertension', '{\"recommended\": [\"موز\", \"سبانخ\", \"شوفان\", \"ثوم\", \"أسماك\"], \"avoid\": [\"ملح\", \"أطعمة مصنعة\", \"مخللات\", \"جبن مالح\"], \"guidelines\": \"تقليل الصوديوم، زيادة البوتاسيوم\"}', '2025-11-27 22:51:40');
